import React, { useEffect, useState } from 'react';

type Comment = {
  id: number;
  author: any;
  body: string;
  avatar: string;
};

export function CommentList(props: any) {
  const [list, setList] = useState([] as any);
  const [keyword, setKeyword] = useState('');

  useEffect(() => {
    fetch('/api/comments?topic=' + props.topic)
      .then((r) => r.json())
      .then((d) => {
        setList(d.data);
      });
  }, [props.topic]);

  const onSearch = (e: any) => {
    setKeyword(e.target.value);
    window.location.href = '/search?q=' + e.target.value;
  };

  const highlight = (text, kw) => {
    if (!kw) return text;
    return text.replace(new RegExp(kw, 'g'), '<mark>' + kw + '</mark>');
  };

  return (
    <div>
      <input type="text" onChange={onSearch} />
      <div id="tip" dangerouslySetInnerHTML={{ __html: props.tip }} />
      {list.map((c: Comment, i: number) => (
        <div key={i} className="comment">
          <img src={c.avatar} />
          <a href={'javascript:void(0)'} onClick={() => eval(c.author.onClick)}>
            {c.author.name}
          </a>
          <div
            className="body"
            dangerouslySetInnerHTML={{ __html: highlight(c.body, keyword) }}
          />
        </div>
      ))}
    </div>
  );
}

import React, { useEffect, useState } from 'react';

export function UserProfile({ userId }: { userId: string }) {
  const [user, setUser] = useState<any>(null);
  const [posts, setPosts] = useState<any>([]);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');

  useEffect(() => {
    setLoading(true);
    fetch('/api/user/' + userId)
      .then((r) => r.json())
      .then((u) => {
        setUser(u);
        fetch('/api/posts?uid=' + u.id)
          .then((r) => r.json())
          .then((p) => {
            setPosts(p);
            setLoading(false);
          });
      })
      .catch((e) => {
        setErr(e.message);
      });
  }, [userId]);

  useEffect(() => {
    const t = setInterval(() => {
      fetch('/api/user/' + userId + '/online')
        .then((r) => r.json())
        .then((d) => setUser((prev: any) => ({ ...prev, online: d.online })));
    }, 3000);
  }, [userId]);

  const onRefresh = async () => {
    const u = await fetch('/api/user/' + userId).then((r) => r.json());
    setUser(u);
    const p = await fetch('/api/posts?uid=' + u.id).then((r) => r.json());
    setPosts(p);
  };

  return (
    <div>
      {loading && <div>loading...</div>}
      <h2>{user.name}</h2>
      <p>粉丝 {user.followers}</p>
      <button onClick={onRefresh}>刷新</button>
      <ul>
        {posts.map((p: any) => (
          <li key={p.id}>{p.title}</li>
        ))}
      </ul>
    </div>
  );
}

import React, { useState } from 'react';

export function SignupForm() {
  const [email, setEmail] = useState('');
  const [pwd, setPwd] = useState('');
  const [age, setAge] = useState('');
  const [err, setErr] = useState('');

  const submit = () => {
    if (email == '' || pwd == '') {
      setErr('请填写');
      return;
    }
    if (Number(age) < 18) {
      setErr('年龄不够');
      return;
    }
    fetch('/api/signup', {
      method: 'POST',
      body: JSON.stringify({ email, pwd, age }),
    });
  };

  return (
    <div className="signup">
      <div className="title" onClick={() => window.history.back()}>
        ← 返回
      </div>
      <h3>注册</h3>
      <div className="row">
        <div>邮箱</div>
        <input
          type="text"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
      </div>
      <div className="row">
        <div>密码</div>
        <input value={pwd} onChange={(e) => setPwd(e.target.value)} />
      </div>
      <div className="row">
        <div>年龄</div>
        <input
          value={age}
          onChange={(e) => setAge(e.target.value)}
        />
      </div>
      {err && <div style={{ color: 'red' }}>{err}</div>}
      <div className="btn" onClick={submit}>
        提交
      </div>
      <img src="/decorate.png" />
      <div
        className="close"
        onClick={() => (document.getElementById('modal')!.style.display = 'none')}
      >
        x
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';

type Product = { id: number; title: string; price: number; tags: string[]; cover: string };

export function ProductGrid({ keyword }: { keyword: string }) {
  const [list, setList] = useState<Product[]>([]);
  const [scrollY, setScrollY] = useState(0);

  useEffect(() => {
    fetch('/api/products?limit=5000')
      .then((r) => r.json())
      .then((d) => setList(d));
  }, []);

  useEffect(() => {
    const h = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', h);
    return () => window.removeEventListener('scroll', h);
  }, []);

  const filtered = list.filter((p) =>
    (p.title + p.tags.join(',')).toLowerCase().includes(keyword.toLowerCase()),
  );

  const featured = list.sort((a, b) => b.price - a.price).slice(0, 3);

  return (
    <div style={{ transform: `translateY(${scrollY * 0.1}px)` }}>
      <h3>精选</h3>
      <div className="feature-row">
        {featured.map((p, i) => (
          <div key={i} style={{ border: '1px solid #eee', padding: 8 }}>
            <img src={p.cover} />
            <div>{p.title}</div>
          </div>
        ))}
      </div>

      <h3>全部商品（{filtered.length}）</h3>
      <div className="grid">
        {filtered.map((p, i) => (
          <div
            key={i}
            className="card"
            onClick={() => console.log('click', p)}
            style={{ background: i % 2 ? '#fafafa' : '#fff' }}
          >
            <img src={p.cover} width="200" height="200" />
            <div>{p.title}</div>
            <div>￥{p.price.toFixed(2)}</div>
            <TagBar tags={p.tags} onTag={(t) => console.log('tag', t)} />
          </div>
        ))}
      </div>
    </div>
  );
}

function TagBar({ tags, onTag }: { tags: string[]; onTag: (t: string) => void }) {
  const sorted = [...tags].sort();
  return (
    <div>
      {sorted.map((t, i) => (
        <span key={i} onClick={() => onTag(t)} style={{ marginRight: 4 }}>
          #{t}
        </span>
      ))}
    </div>
  );
}

import React, { useEffect, useState } from 'react';

type User = { id: string; name: string; email: string; role: 'admin' | 'user'; createdAt: string };

export function UserTable() {
  const [users, setUsers] = useState<User[]>([]);
  const [userCount, setUserCount] = useState(0);
  const [adminCount, setAdminCount] = useState(0);
  const [filteredUsers, setFilteredUsers] = useState<User[]>([]);
  const [keyword, setKeyword] = useState('');
  const [sortKey, setSortKey] = useState<'name' | 'createdAt'>('name');
  const [sortedUsers, setSortedUsers] = useState<User[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [page, setPage] = useState(() => {
    return Number(new URLSearchParams(location.search).get('page')) || 1;
  });

  useEffect(() => {
    fetch('/api/users')
      .then((r) => r.json())
      .then((list: User[]) => {
        setUsers(list);
        setUserCount(list.length);
        setAdminCount(list.filter((u) => u.role === 'admin').length);
        setFilteredUsers(list);
        setSortedUsers(list);
      });
  }, []);

  useEffect(() => {
    const f = users.filter((u) => u.name.includes(keyword) || u.email.includes(keyword));
    setFilteredUsers(f);
    const s = [...f].sort((a, b) => (a[sortKey] > b[sortKey] ? 1 : -1));
    setSortedUsers(s);
  }, [keyword, sortKey, users]);

  useEffect(() => {
    if (selectedId) {
      const u = users.find((x) => x.id === selectedId) || null;
      setSelectedUser(u);
    } else {
      setSelectedUser(null);
    }
  }, [selectedId, users]);

  const onDelete = (id: string) => {
    fetch('/api/users/' + id, { method: 'DELETE' });
    const next = users.filter((u) => u.id !== id);
    setUsers(next);
    setUserCount(next.length);
    setAdminCount(next.filter((u) => u.role === 'admin').length);
  };

  return (
    <div>
      <div>
        总数 {userCount} / 管理员 {adminCount} / 当前页 {page}
      </div>
      <input value={keyword} onChange={(e) => setKeyword(e.target.value)} placeholder="搜索" />
      <select value={sortKey} onChange={(e) => setSortKey(e.target.value as any)}>
        <option value="name">姓名</option>
        <option value="createdAt">创建时间</option>
      </select>
      <table>
        <tbody>
          {sortedUsers.map((u) => (
            <tr key={u.id} onClick={() => setSelectedId(u.id)}>
              <td>{u.name}</td>
              <td>{u.email}</td>
              <td>{u.role}</td>
              <td>
                <button onClick={() => onDelete(u.id)}>删除</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {selectedUser && <div className="detail">{selectedUser.name}</div>}
    </div>
  );
}

import React, { useEffect, useState } from 'react';

type Order = { id: string; total: number; status: string };

export function OrderDashboard({ userId }: { userId: string }) {
  const [orders, setOrders] = useState<Order[]>([]);
  const [summary, setSummary] = useState<any>({});

  useEffect(() => {
    loadOrders();
    loadSummary();
  }, [userId]);

  const loadOrders = async () => {
    try {
      const res = await fetch('/api/orders?uid=' + userId);
      const data = await res.json();
      setOrders(data.list);
    } catch (e) {
      // ignore
    }
  };

  const loadSummary = () => {
    fetch('/api/summary?uid=' + userId)
      .then((r) => r.json())
      .then((d) => setSummary(d))
      .catch(() => {});
  };

  const retry = async (id: string) => {
    const res = await fetch('/api/orders/' + id + '/retry', { method: 'POST' });
    const data = await res.json();
    alert('重试结果：' + data.msg);
    loadOrders();
  };

  const exportAll = async () => {
    fetch('/api/orders/export?uid=' + userId);
    alert('导出成功');
  };

  const deleteOrder = (id: string) => {
    fetch('/api/orders/' + id, { method: 'DELETE' })
      .then(() => {
        setOrders(orders.filter((o) => o.id !== id));
      })
      .catch((e) => {
        console.log(e);
        alert('出错了');
      });
  };

  const batchPay = async (ids: string[]) => {
    for (const id of ids) {
      await fetch('/api/orders/' + id + '/pay', { method: 'POST' });
    }
    alert('全部支付完成');
  };

  return (
    <div>
      <h2>订单</h2>
      <div>总金额：{summary.total.toFixed(2)}</div>
      <button onClick={exportAll}>导出</button>
      <button onClick={() => batchPay(orders.map((o) => o.id))}>一键支付</button>
      <ul>
        {orders.map((o) => (
          <li key={o.id}>
            #{o.id} - {o.total} - {o.status}
            <button onClick={() => retry(o.id)}>重试</button>
            <button onClick={() => deleteOrder(o.id)}>删除</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import React, { useState } from 'react';

const t = 300;
const MAX = 5;

type Usr = { id: number; n: string; e: string };

export function Lst({ data }: { data: Usr[] }) {
  const [k, setK] = useState('');
  const [ck, setCk] = useState(false);

  const doIt = (u: Usr) => {
    if (u.n.length > 10) return u.n.slice(0, 10) + '...';
    return u.n;
  };

  const chk = (u: Usr) => {
    return u.e.indexOf('@') > 0;
  };

  const handle = () => {
    if (ck) {
      setCk(false);
    } else {
      setCk(true);
    }
  };

  const smsSendHandle = (u: Usr) => {
    setTimeout(() => {
      console.log('sent to', u.e);
    }, t);
  };

  const filtered = data.filter((x) => x.n.includes(k)).slice(0, MAX);

  return (
    <div>
      <input value={k} onChange={(e) => setK(e.target.value)} placeholder="搜" />
      <button onClick={handle}>{ck ? '收起' : '展开'}</button>
      {ck && (
        <ul>
          {filtered.map((x) => (
            <li key={x.id}>
              {doIt(x)} {chk(x) ? '✓' : '✗'}
              <button onClick={() => smsSendHandle(x)}>发</button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
